CREATE TABLE `reviews` (`id` CHAR(36) NOT NULL,`customer_user_id` CHAR(36) NOT NULL,`store_id` CHAR(36) NOT NULL,`rating` INTEGER NOT NULL,`comment` TEXT NULL,`visibility` ENUM('VISIBLE','HIDDEN') NOT NULL DEFAULT 'VISIBLE',`moderation_reason` TEXT NULL,`moderated_by_user_id` CHAR(36) NULL,`moderated_at` DATETIME(3) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,INDEX `reviews_store_id_visibility_created_at_idx`(`store_id`,`visibility`,`created_at`),INDEX `reviews_customer_user_id_created_at_idx`(`customer_user_id`,`created_at`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `review_photos` (`id` CHAR(36) NOT NULL,`review_id` CHAR(36) NOT NULL,`url` VARCHAR(2000) NOT NULL,`storage_key` VARCHAR(500) NULL,`position` INTEGER NOT NULL,UNIQUE INDEX `review_photos_review_id_position_key`(`review_id`,`position`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `review_replies` (`id` CHAR(36) NOT NULL,`review_id` CHAR(36) NOT NULL,`author_user_id` CHAR(36) NOT NULL,`text` TEXT NOT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,UNIQUE INDEX `review_replies_review_id_key`(`review_id`),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `product_review_targets` (`review_id` CHAR(36) NOT NULL,`commerce_order_item_id` CHAR(36) NOT NULL,UNIQUE INDEX `product_review_targets_commerce_order_item_id_key`(`commerce_order_item_id`),PRIMARY KEY (`review_id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `tourism_review_targets` (`review_id` CHAR(36) NOT NULL,`tourism_booking_id` CHAR(36) NOT NULL,UNIQUE INDEX `tourism_review_targets_tourism_booking_id_key`(`tourism_booking_id`),PRIMARY KEY (`review_id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `live_in_review_targets` (`review_id` CHAR(36) NOT NULL,`live_in_booking_id` CHAR(36) NOT NULL,UNIQUE INDEX `live_in_review_targets_live_in_booking_id_key`(`live_in_booking_id`),PRIMARY KEY (`review_id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `reviews` ADD CONSTRAINT `reviews_customer_user_id_fkey` FOREIGN KEY (`customer_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,ADD CONSTRAINT `reviews_store_id_fkey` FOREIGN KEY (`store_id`) REFERENCES `stores`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE,ADD CONSTRAINT `reviews_moderated_by_user_id_fkey` FOREIGN KEY (`moderated_by_user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `review_photos` ADD CONSTRAINT `review_photos_review_id_fkey` FOREIGN KEY (`review_id`) REFERENCES `reviews`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `review_replies` ADD CONSTRAINT `review_replies_review_id_fkey` FOREIGN KEY (`review_id`) REFERENCES `reviews`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,ADD CONSTRAINT `review_replies_author_user_id_fkey` FOREIGN KEY (`author_user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `product_review_targets` ADD CONSTRAINT `product_review_targets_review_id_fkey` FOREIGN KEY (`review_id`) REFERENCES `reviews`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,ADD CONSTRAINT `product_review_targets_commerce_order_item_id_fkey` FOREIGN KEY (`commerce_order_item_id`) REFERENCES `commerce_order_items`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `tourism_review_targets` ADD CONSTRAINT `tourism_review_targets_review_id_fkey` FOREIGN KEY (`review_id`) REFERENCES `reviews`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,ADD CONSTRAINT `tourism_review_targets_tourism_booking_id_fkey` FOREIGN KEY (`tourism_booking_id`) REFERENCES `tourism_bookings`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `live_in_review_targets` ADD CONSTRAINT `live_in_review_targets_review_id_fkey` FOREIGN KEY (`review_id`) REFERENCES `reviews`(`id`) ON DELETE CASCADE ON UPDATE CASCADE,ADD CONSTRAINT `live_in_review_targets_live_in_booking_id_fkey` FOREIGN KEY (`live_in_booking_id`) REFERENCES `live_in_bookings`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
